const token = $json?.query?.validationToken;

if (token) {
  // Graph exige texto plano, no JSON
  return [
    {
      json: {
        statusCode: 200,
        headers: { "Content-Type": "text/plain" },
        body: token
      }
    }
  ];
}

const data = $input.last().json;

const subscriptionId = data.subscriptionId;
if (!subscriptionId) {
  throw new Error('No hay subscriptionId en Sheets. Ejecuta primero el flujo de Crear Suscripción.');
}

const expDate = new Date(data.expiration);
if (isNaN(expDate.getTime())) {
  throw new Error('Fecha de expiración inválida en Sheets: ' + data.expiration);
}

const now = Date.now();
const msLeft = expDate.getTime() - now;
const daysLeft = msLeft / (1000 * 60 * 60 * 24);

console.log(`Suscripción: ${subscriptionId}`);
console.log(`Expira: ${data.expiration}`);
console.log(`Días restantes: ${daysLeft.toFixed(2)}`);

return [{
  json: {
    subscriptionId,
    expiration: data.expiration,
    daysLeft: parseFloat(daysLeft.toFixed(2)),
    needsRenewal: daysLeft < 7
  }
}];

const d = $input.first().json;
const msg = `✅ Suscripción OK | ID: ${d.subscriptionId} | Expira en: ${d.daysLeft} días (${d.expiration})`;
console.log(msg);
return [{ json: { status: 'ok', message: msg, daysLeft: d.daysLeft, subscriptionId: d.subscriptionId } }];

const d = $input.first().json;
const newExpiration = new Date(Date.now() + 29 * 24 * 60 * 60 * 1000).toISOString();
console.log(`⚠️ Renovando suscripción ${d.subscriptionId} | Días restantes: ${d.daysLeft} | Nueva exp: ${newExpiration}`);
return [{ json: { subscriptionId: d.subscriptionId, expirationDateTime: newExpiration } }];

const r = $input.first().json;
return [{ json: {
  subscriptionId: r.id,
  expiration: r.expirationDateTime,
  renewedAt: new Date().toISOString(),
  method: 'PATCH'
}}];

const d = $input.first().json;
const msg = `🔄 Suscripción Graph RENOVADA\nID: ${d.subscriptionId}\nNueva expiración: ${d.expiration}\nRenovada: ${d.renewedAt}`;
console.log(msg);
return [{ json: { status: 'renewed', message: msg, subscriptionId: d.subscriptionId, newExpiration: d.expiration, renewedAt: d.renewedAt } }];

const r = $input.first().json;
if (!r.id) {
  throw new Error('ERROR CRÍTICO: Falló la re-creación de suscripción. Respuesta Graph: ' + JSON.stringify(r) + '. Revisa credenciales OAuth2 y que el webhook esté activo.');
}
console.log('⚠️ Suscripción re-creada:', r.id, '| Expira:', r.expirationDateTime);
return [{ json: {
  subscriptionId: r.id,
  expiration: r.expirationDateTime,
  createdAt: new Date().toISOString(),
  method: 'POST_RECREATED'
}}];

const d = $input.first().json;
const msg = `🚨 ALERTA: Suscripción Graph EXPIRADA y RE-CREADA
Nuevo ID: ${d.subscriptionId}
Nueva expiración: ${d.expiration}
Creada: ${d.createdAt}

⚠️ Verifica que el flujo de SharePoint esté recibiendo notificaciones.`;
console.log(msg);
return [{ json: { status: 'recreated', message: msg, newSubscriptionId: d.subscriptionId, newExpiration: d.expiration, createdAt: d.createdAt } }];

